do
    local d=ForeverSourceData
    d.acquisitionCrossLinks={added=0,vendor=0,crafted=0,quest=0}
    local c=d.acquisitionCrossLinks
    local keys={}
    local function add(itemID,row)
        itemID=tonumber(itemID)
        if not itemID or itemID<=0 then return end
        local item=d.items[itemID] or d.items[tostring(itemID)]
        if not item then item={name="Item "..itemID};d.items[itemID]=item end
        item.sources=item.sources or {}
        local index=keys[itemID]
        if not index then
            index={} keys[itemID]=index
            for _,v in pairs(item.sources) do
                if type(v)=="table" then index[tostring(v.type)..":"..tostring(tonumber(v.id or v.questID or v.spellID or v.recipeID))]=true end
            end
        end
        local key=tostring(row.type)..":"..tostring(tonumber(row.id or row.questID or row.spellID or row.recipeID))
        if index[key] then return end
        index[key]=true table.insert(item.sources,row)
        c.added=c.added+1;c[row.type]=(c[row.type] or 0)+1
    end
    for rawID,rows in pairs(d.vendors or {}) do
        local id=tonumber(rawID)
        if id then
            local npc=(d.npcs or {})[id] or (d.foreverNPCs or {})[id] or {}
            for _,r in pairs(rows) do if type(r)=="table" and tonumber(r.itemID) then
                add(r.itemID,{type="vendor",id=id,name=npc.name or ("NPC "..id),buyPrice=r.buyPrice,buyCount=r.buyCount,maxCount=r.maxCount,extendedCost=r.extendedCost,restockSeconds=r.restockSeconds,locations=(d.npcLocations or {})[id],source="Recorded ForeverDB vendor inventory; reverse link"})
            end end
        end
    end
    for rawID,r in pairs(d.recipes or {}) do if type(r)=="table" then
        local id=tonumber(rawID) or tonumber(r.id or r.spellID)
        local itemID=tonumber(r.createsItemID or r.createdItemID or r.itemID or r.creates)
        if id and itemID then add(itemID,{type="crafted",spellID=id,id=id,name=r.name or ("Recipe "..id),skillID=r.skillID,requiredSkill=r.requiredSkill,source=r.dataSource or "Recorded ForeverDB recipe output; reverse link"}) end
    end end
    for rawID,q in pairs(d.quests or {}) do if type(q)=="table" then
        local id=tonumber(rawID) or tonumber(q.id)
        if id then for _,field in ipairs({"rewardItems","choiceRewardItems"}) do
            for _,reward in pairs(type(q[field])=="table" and q[field] or {}) do if type(reward)=="table" then
                add(reward.itemID or reward.id,{type="quest",id=id,questID=id,name=q.name or ("Quest "..id),rewardCount=reward.count,choiceReward=field=="choiceRewardItems",source=q.dataSource or "Recorded ForeverDB quest reward; reverse link"})
            end end
        end end
    end end
end
-- FOREVER_ENRICHMENT_COMPLETE
end applyRecordedData() end

-- FOREVER_REPORTED_VENDOR_232_BEGIN
do
    local d=ForeverSourceData
    if d then
        d.items=d.items or {} d.npcs=d.npcs or {} d.vendors=d.vendors or {}
        local npcID=256733
