 if d then
  local stats={associations=0,added=0,recipes=0} local touched={}
  for rawNPC,inventory in pairs(d.trainers or {}) do
   local npcID=tonumber(rawNPC)
   if npcID and type(inventory)=="table" then
    for _,entry in pairs(inventory) do
     if type(entry)=="table" then
      local spellID=tonumber(entry.learnedSpellID or entry.spellID)
      local recipe=spellID and ((d.recipes or {})[spellID] or (d.recipes or {})[tostring(spellID)])
      if type(recipe)=="table" then
       recipe.trainers=recipe.trainers or recipe.trainerNPCs or {}
       local found=false
       for _,v in pairs(recipe.trainers) do if tonumber(type(v)=="table" and (v.npcID or v.id) or v)==npcID then found=true break end end
       if not found then table.insert(recipe.trainers,npcID) stats.added=stats.added+1 end
       recipe.trainerDetails=recipe.trainerDetails or {}
       if not recipe.trainerDetails[npcID] then
        recipe.trainerDetails[npcID]={npcID=npcID,spellID=spellID,cost=entry.cost,requiredLevel=entry.requiredLevel,requiredSkillID=entry.requiredSkillID,requiredSkillValue=entry.requiredSkillValue,requiredSkillName=entry.requiredSkillName,evidenceStatus="Recorded trainer inventory; not independently verified",source="ForeverSourceData.trainers exact learned-spell match"}
        stats.associations=stats.associations+1
       end
       touched[spellID]=true
      end
     end
    end
   end
  end
  for _ in pairs(touched) do stats.recipes=stats.recipes+1 end
  d.trainerCrossLinks238=stats
 end
end
